def hosted(cases):
    """The cases you can play: those marked hosted, or all of them if the list has no marker."""
    if any(HOSTED_FIELD in c for c in cases):
        return [c for c in cases if c.get(HOSTED_FIELD)]
    return cases


def quota_used_up(error):
    """The practice quota's 429 ("practice limit: …"): retrying does not help before it resets."""
    return isinstance(error, ArenaError) and error.status == 429 and str(error.detail).startswith("practice limit")


def play_all(new_table, case_ids, new_agent, parallel=8):
    """Play many cases at once (e.g. every practice case). `new_table()` and `new_agent()` give
    each case its own table and agent. Once the practice quota is used up, no further case starts.
    Returns {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
                log.warning("practice quota used up: %s", e.detail)
            elif e.status == 403:
                log.warning("%s: %s", case_id, e.detail)  # e.g. not hosted for practice
            else:
                log.exception("%s failed", case_id)
            return case_id, e
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final: wait for each wave, play its cases in parallel within the wave's cap, wait
    for the next. Keep it running from before the first wave until the last has closed; it returns
    after `waves` waves have closed and every case has finished: {case_id: result or exception}."""
    started, closed, caps = {}, set(), {}  # caps: wave -> its cap as time.time()

    def one(case, deadline):
        try:
            return play(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:  # 403: no wave has started yet
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:  # each wave has its own cap; follow an extension
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                        log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}
"""Price commercial exchanges against a buyer cost budget, not a headline price."""

import math

from .cost import RELATIONSHIP_GOALS, cost_breakdown, must_haves_ok, supplier_value, total_cost


def at_cost(case, template, budget, standard=None, supplier=None):
    """Highest cent price within the budget for these exact non-price terms.

    Ordinary cost is affine in price. A strategic relationship penalty can make
    it U-shaped: locate its minimum before searching the upper feasible branch.
    The template is never relaxed to make the arithmetic work.
    """
    if "unit_price" not in case["negotiable"] or not math.isfinite(budget):
        return None
    # The public cost function rounds the *total* to cents. Preserve prices
    # exactly on that boundary; still verify the returned rounded cost below.
    limit = budget + 0.005 - 1e-8

    def terms(price):
        return {**template, "unit_price": price}

    def cash_cost(price):
        return sum(cost_breakdown(case, terms(price), standard).values())

    base = cash_cost(0.01)
    slope = cash_cost(1.01) - base
    if not math.isfinite(slope) or slope <= 0:
        return None  # no positive, identifiable price exposure
    ceiling = 0.01 + (limit - base) / slope
    if ceiling < 0.01 or not math.isfinite(ceiling):
        return None
    lower = 0.01
    b = case["buyer"]
    nonlinear = (
        supplier and b.get("category_goal") in RELATIONSHIP_GOALS
        and b.get("relationship_eur_per_point") and b.get("sustainable_margin_pct")
    )

    def cost(price):
        return sum(cost_breakdown(case, terms(price), standard, supplier).values())

    if nonlinear:
        # Supplier margin is defined only for positive supplier value.
        worth = supplier_value(case, terms(lower), supplier)
        gain = supplier_value(case, terms(lower + 1), supplier) - worth
        if gain <= 0:
            return None
        lower = max(lower, lower - worth / gain + 1e-6)
        if lower > ceiling:
            return None
        left, right = lower, ceiling
        for _ in range(64):
            a, z = (2 * left + right) / 3, (left + 2 * right) / 3
            if cost(a) <= cost(z):
                right = z
            else:
                left = a
        # There may be no feasible cent even when the continuous minimum fits.
        cents = {max(math.ceil(lower * 100), int(p * 100)) for p in (left, right)}
        cents |= {c + 1 for c in cents}
        feasible = [c / 100 for c in cents if c / 100 <= ceiling and cost(c / 100) <= limit]
        if not feasible:
            return None
        lower = max(feasible)
        left, right = lower, ceiling
        for _ in range(48):
            middle = (left + right) / 2
            if cost(middle) <= limit:
                left = middle
            else:
                right = middle
        ceiling = left
    price = math.floor(ceiling * 100 + 1e-7) / 100
    result = terms(price)
    if price < lower - 1e-7 or not must_haves_ok(case, result, standard):
        return None
    return result if total_cost(case, result, standard, supplier) <= budget else None


def same_exchange(left, right):
    """A price concession belongs to its commercial package, not to every package."""
    return {k: v for k, v in left.items() if k != "unit_price"} == {
        k: v for k, v in right.items() if k != "unit_price"
    }


def value_equivalent(case, first, templates, standard, supplier, events):
    """Keep the main bid; offer at most two distinct exchanges at its total cost.

    Do not retract a higher price already offered for identical complete terms.
    If that commitment exceeds today's budget, omit the exchange instead.
    """
    budget = total_cost(case, first, standard, supplier)
    previous = [
        sheet["terms"] for message in events if message.get("from") == "buyer"
        for sheet in message.get("term_sheets") or []
    ]
    out = [first]
    for template in templates:
        if any(same_exchange(template, existing) for existing in out):
            continue
        priced = at_cost(case, template, budget, standard, supplier)
        if priced is None:
            continue
        if any(same_exchange(priced, old) and priced["unit_price"] < old["unit_price"] for old in previous):
            continue
        out.append(priced)
        if len(out) == 3:
            break
    return out
