comparisons={}
for split in ['dev','holdout']:
    ref=json.load(open(f'/tmp/competitive-reference-{split}.json'))
    cand=json.load(open(f'/tmp/competitive-protected-{split}.json'))
    rows=[]
    for a,b in zip(ref['runs'],cand['runs'],strict=True):
        rows.append({'case_id':a['case_id'],'family':a['family'],'style':a['style'],'reference_score':a['result']['score'],'candidate_score':b['result']['score'],'reference_cost':a['result']['c_deal'],'candidate_cost':b['result']['c_deal'],'must_haves_ok':b['result'].get('must_haves_ok')})
    changes=[r['candidate_score']-r['reference_score'] for r in rows]
    comparisons[split]={'reference':{k:v for k,v in ref.items() if k!='runs'},'candidate':{k:v for k,v in cand.items() if k!='runs'},'improved':sum(d>1e-8 for d in changes),'tied':sum(abs(d)<=1e-8 for d in changes),'regressed':sum(d< -1e-8 for d in changes),'cases':rows}
    print(split,comparisons[split]['improved'],comparisons[split]['tied'],comparisons[split]['regressed'])
