    previous = {'unit_price': round(price * .95, 2), 'payment_days': 14,
                'contract_months': 36, 'index_clause': clause}
    supplier = {**previous, 'unit_price': price}
    events = [reply(supplier), {'from': 'buyer', 'term_sheets': [{'terms': previous}]}, reply(supplier)]
    offers = BuyerAgent().packages(case, case['suppliers'][0], events)
    matched = next(t for t in offers if same_exchange(t, previous))
    assert previous['unit_price'] < matched['unit_price'] < price
    # The commitment stays below the supplier ask in full-cost terms too.
    assert total_cost(case, previous) < total_cost(case, matched) < total_cost(case, supplier)


def test_first_offer_includes_linked_material_finance_and_duration(case):
    offers = BuyerAgent().packages(case, case['suppliers'][0], [reply({
        'unit_price': 230, 'payment_days': 30, 'contract_months': 12, 'index_clause': None,
    })])
    assert len(offers) <= 3
    assert all(must_haves_ok(case, t) for t in offers)
    assert any(t['payment_days'] == 14 and t['contract_months'] == 36 and t['index_clause'] for t in offers)
    # A short contract must not become our lead offer by shifting the balance
    # of the need into expensive fallback purchases.
    assert offers[0]['contract_months'] >= 24
    assert max(total_cost(case, t) for t in offers) <= total_cost(case, offers[0])


