def test_failed_model_preflight_cannot_open_hosted_session(case, monkeypatch, tmp_path):
    def broken(*_):
        raise httpx.HTTPStatusError('private endpoint and key must not be logged',
            request=httpx.Request('POST', 'https://private.invalid'), response=httpx.Response(429))

    class Client:
        def cases(self, _):
            return [case]

        def me(self):
            return {'practice': {'left': 10}}

    opened = []
    monkeypatch.setattr('arena_kit.evaluation.RemoteTable', lambda *_: opened.append(True))
    path = tmp_path / 'failed.json'
    with pytest.raises(RuntimeError, match='HTTP 429'):
        evaluate(Client(), lambda: BuyerAgent(complete=broken), [case['case_id']], out=path)
    report = json.loads(path.read_text())
    assert opened == [] and report['runs'] == []
    assert report['model_preflight']['ok'] is False
    assert 'private' not in path.read_text()


@pytest.mark.parametrize('response', ['not json', '{"tactic":"unknown"}',
    '{"tactic":"cash","evidence":[0],"message":"Please compare the packages."}'])
def test_preflight_rejects_invalid_tactical_output(case, response):
    with pytest.raises(RuntimeError, match='preflight failed'):
        BuyerAgent(complete=lambda *_: response).preflight(case)


def test_preflight_accepts_grounded_model_response(case):
    def complete(_, user):
        assert 'binding_commitment' in json.loads(user)
        return json.dumps({'tactic': 'cost', 'evidence': [], 'message': 'Please compare the complete packages.'})
    result = BuyerAgent(complete=complete).preflight(case)
    assert result['ok'] and result['mode'] == 'model'

